"""Minimal YAML renderer (standard library only)."""

from plugins import PluginError, Renderer, register


def _yaml_value(v):
    """Return the YAML scalar string for a Python value."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return repr(v)
    if isinstance(v, str):
        # Quote strings that could be misinterpreted or contain special chars
        if v == "" or v in ("true", "false", "null", "yes", "no", "on", "off"):
            return f'"{v}"'
        if any(c in v for c in ":{}[]&*?|->!%@`,#"):
            return f'"{v}"'
        if v.startswith((" ", "\t")) or v.endswith((" ", "\t")):
            return f'"{v}"'
        return v
    return str(v)


def _yaml_key(k):
    """Return the YAML key string (always quoted to be safe)."""
    return f'"{k}"'


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines: list[str] = []
        for row in rows:
            lines.append("-")
            for k, v in row.items():
                lines.append(f"  {_yaml_key(k)}: {_yaml_value(v)}")
        return "\n".join(lines) + "\n"

