"""Simple YAML renderer (standard library only)."""

from plugins import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Render a scalar value as a YAML scalar string."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return str(value)
    # str
    s = str(value)
    # Quote if the value could be misinterpreted
    if s == "" or s in ("true", "false", "null", "yes", "no", "on", "off",
                         "True", "False", "Null", "Yes", "No", "On", "Off",
                         "y", "n", "Y", "N"):
        return f"'{s}'"
    # Quote if it looks like a number
    try:
        float(s)
        return f"'{s}'"
    except ValueError:
        pass
    # Quote if it starts/ends with whitespace or contains special chars
    if s[0] in (' ', '\t') or s[-1] in (' ', '\t') or ':' in s or '#' in s:
        return f"'{s}'"
    return s


def _yaml_value(value, indent: int) -> str:
    """Render a value (scalar or list) as YAML lines."""
    if isinstance(value, list):
        lines = []
        prefix = "  " * indent
        for item in value:
            if isinstance(item, dict):
                # nested dict as block
                lines.append(f"{prefix}-")
                for k, v in item.items():
                    lines.append(f"{prefix}  {_yaml_key(k)}: {_yaml_value(v, indent + 2)}")
            else:
                lines.append(f"{prefix}- {_yaml_scalar(item)}")
        return "\n".join(lines)
    if isinstance(value, dict):
        lines = []
        prefix = "  " * indent
        for k, v in value.items():
            lines.append(f"{prefix}{_yaml_key(k)}: {_yaml_value(v, indent + 1)}")
        return "\n".join(lines)
    return _yaml_scalar(value)


def _yaml_key(key: str) -> str:
    """Render a mapping key."""
    s = str(key)
    if s == "" or s in ("true", "false", "null", "yes", "no", "on", "off",
                         "True", "False", "Null", "Yes", "No", "On", "Off"):
        return f"'{s}'"
    return s


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for row in rows:
            lines.append("-")
            for k, v in row.items():
                lines.append(f"  {_yaml_key(k)}: {_yaml_value(v, 2)}")
        return "\n".join(lines) + "\n"

